import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"规范与多语言","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/spec.md","filePath":"appendix/spec.md","lastUpdated":1794052435000}`),a={name:`appendix/spec.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="规范与多语言" tabindex="-1">规范与多语言 <a class="header-anchor" href="#规范与多语言" aria-label="Permalink to “规范与多语言”">​</a></h1><p>XiHan Framework 的本体不是 .NET 代码，而是一份语言中立的规范：XiHan Spec。.NET 实现是它的参考实现，Go SDK 是第二个实现，其他语言按同一份规范实现并通过同一套一致性测试。这一页讲规范怎样组织、哪些内容是规范性的、一致性测试怎样工作，以及各语言 SDK 的现状。要写插件或另一种语言的 SDK 的读者需要读它；只用 .NET 的读者了解即可。</p><h2 id="为什么要有规范" tabindex="-1">为什么要有规范 <a class="header-anchor" href="#为什么要有规范" aria-label="Permalink to “为什么要有规范”">​</a></h2><p>「同一个名字各语言都能用」这件事，只有两条路：要么每种语言各写一个风格相似的框架，然后在文档里宣称它们是一家；要么先写下语言中立的语义，再让每种实现去通过同一套测试。前者做出来的东西经不起细看，后者才是 OpenTelemetry、MCP、CloudEvents 走通的路。我选了后者。</p><p>规范还解决一个 .NET 内部的问题：公开契约先写进规范，再写架构决策记录，再写代码与一致性向量。没有 RFC 的公开 API 变更不合并。这条流程让「随手加一个公开方法」变得不可能，也让每个设计决定都有据可查。</p><h2 id="规范仓库" tabindex="-1">规范仓库 <a class="header-anchor" href="#规范仓库" aria-label="Permalink to “规范仓库”">​</a></h2><p>规范在独立仓库 <a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">XiHanFun/framework-spec</a>，.NET 实现以子模块引用它到 <code>framework/spec</code>，Go SDK 引用到 <code>spec</code>。目录结构：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spec/</span></span>
<span class="line"><span>├─ rfcs/           提案：先 RFC，再 ADR，再实现</span></span>
<span class="line"><span>├─ conventions/    规范性：术语表、包 ID、能力 ID、操作 ID、错误码、Baggage 键、批量优先</span></span>
<span class="line"><span>├─ manifest/       规范性：xihan.manifest.json 的 JSON Schema</span></span>
<span class="line"><span>├─ plugin/         规范性：插件协议 plugin.proto 与握手、生命周期、调用；Wasm 载体</span></span>
<span class="line"><span>├─ protocol/       规范性：HTTP、gRPC、MCP、CloudEvents、命令行的映射</span></span>
<span class="line"><span>├─ packaging/      规范性：应用清单 xihan.app.json 与 xihan pack 的产物映射</span></span>
<span class="line"><span>├─ provider/       规范性：远程 Provider 的通用规则与各能力的操作集</span></span>
<span class="line"><span>├─ migration/      规范性：xihan migrate 的通用约定</span></span>
<span class="line"><span>└─ conformance/    一致性向量与黑盒运行器</span></span></code></pre></div><h2 id="规范性与信息性" tabindex="-1">规范性与信息性 <a class="header-anchor" href="#规范性与信息性" aria-label="Permalink to “规范性与信息性”">​</a></h2><p>不是所有东西都要各语言一致。规范把内容分成两类：</p><table tabindex="0"><thead><tr><th>规范性（各语言必须一致）</th><th>信息性（各语言自选）</th></tr></thead><tbody><tr><td>原语语义与线上编码（<code>Result</code>、<code>Error</code>、<code>Maybe</code> 的 JSON 形态）</td><td>内部 API 形态</td></tr><tr><td>清单 Schema</td><td>包管理与目录布局</td></tr><tr><td>上下文传播键与载体</td><td>日志实现</td></tr><tr><td>管道阶段名与排序规则</td><td>具体中间件</td></tr><tr><td>插件协议</td><td>隔离机制</td></tr><tr><td>协议映射（路由推导、错误信封）</td><td>服务器实现</td></tr><tr><td>术语表、错误码、能力 ID、操作 ID、包 ID 命名</td><td>代码风格</td></tr><tr><td>批量优先：集合入参、原生批量、部分失败语义</td><td>批次大小</td></tr></tbody></table><p>举例说，<code>orders.create</code> 在任何语言的实现里都推导为 <code>POST /orders</code>，失败时都返回 RFC 9457 的 Problem Details，错误码都是 <code>&lt;领域大写&gt;_&lt;KIND&gt;_&lt;三位序号&gt;</code>；但 Go 用 <code>context.Context</code> 传递取消、.NET 用 <code>CancellationToken</code>，这是各语言自己的事。</p><h2 id="一致性测试" tabindex="-1">一致性测试 <a class="header-anchor" href="#一致性测试" aria-label="Permalink to “一致性测试”">​</a></h2><p>一致性有两层：</p><table tabindex="0"><thead><tr><th>层</th><th>形式</th><th>谁用</th></tr></thead><tbody><tr><td>数据驱动向量</td><td><code>conformance/vectors/</code> 下的 JSON 文件：<code>Result</code> 与 <code>Error</code> 编码、清单校验、版本解析、管道排序、上下文传播、包 ID 与能力 ID 文法</td><td>各语言 SDK 的单元测试直接读取</td></tr><tr><td>黑盒运行器</td><td><code>xihan-conformance plugin --dir &lt;插件目录&gt;</code>：以宿主身份启动任意语言写的进程外插件，核对握手行与版本协商、清单一致性、生命周期、未知操作的拒绝、声明的操作都返回状态、订阅投递确认、stdin 关闭即退出</td><td>插件作者、远程 Provider 作者</td></tr></tbody></table><p>.NET 侧另有每个子系统的 <code>&lt;领域&gt;.Conformance</code> 包，是 xUnit 套件：默认实现与 Provider 都要通过，远程 Provider 跑同一套。用法见<a href="/testing/conformance">一致性套件与门禁</a>。</p><p>SDK 按成熟度分级：Reference（.NET）、Stable（通过全部向量）、Experimental（部分向量）、Community（社区维护）。</p><h2 id="各语言-sdk" tabindex="-1">各语言 SDK <a class="header-anchor" href="#各语言-sdk" aria-label="Permalink to “各语言 SDK”">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>包名</th><th>仓库</th><th>状态</th></tr></thead><tbody><tr><td>.NET</td><td><code>XiHan.Framework.*</code></td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHan.Framework</a></td><td>参考实现</td></tr><tr><td>Go</td><td><code>github.com/xihanfun/framework-sdk-go</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-go" target="_blank" rel="noreferrer">framework-sdk-go</a></td><td>通过全部向量；用于进程外插件与远程 Provider</td></tr><tr><td>TypeScript</td><td>npm 组织 <code>@xihan-framework/*</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-typescript" target="_blank" rel="noreferrer">framework-sdk-typescript</a></td><td>占位，Go 之后的下一个</td></tr><tr><td>Rust</td><td>crate <code>xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-rust" target="_blank" rel="noreferrer">framework-sdk-rust</a></td><td>占位，面向进程外与 Wasm 插件</td></tr><tr><td>Java</td><td><code>com.xihanfun:xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-java" target="_blank" rel="noreferrer">framework-sdk-java</a></td><td>占位</td></tr><tr><td>Python</td><td><code>xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-python" target="_blank" rel="noreferrer">framework-sdk-python</a></td><td>占位</td></tr><tr><td>PHP</td><td><code>xihanfun/xihan-framework</code></td><td><a href="https://github.com/XiHanFun/framework-sdk-php" target="_blank" rel="noreferrer">framework-sdk-php</a></td><td>占位</td></tr></tbody></table><p>各语言的领域词与术语表一致，只换大小写风格。</p><p>为什么 Go 先行：它离 C# 最远，能证明规范不是 .NET 形状的；同时它适合承载进程外插件、黑盒运行器和将来的 Kubernetes Operator。Go SDK 已经做到的事：用 Go 写的插件在 .NET 宿主里服务一个操作，崩溃时宿主降级而不退出；用 Go 实现的分布式缓存经远程 Provider 适配器通过 .NET 的缓存一致性套件。示例见 <code>framework/samples/EchoGoPlugin</code> 与 <code>CacheGoPlugin</code>，写法见<a href="/plugins/out-of-process">进程外插件</a>。</p><h2 id="变更流程" tabindex="-1">变更流程 <a class="header-anchor" href="#变更流程" aria-label="Permalink to “变更流程”">​</a></h2><p>公开契约的变更按固定顺序走：</p><ol><li>在 <code>rfcs/</code> 新建提案，状态为草案。</li><li>评审通过后写架构决策记录，RFC 状态改为已采纳，正文并入对应的规范性目录。</li><li>实现与一致性向量随 RFC 一起合并。</li></ol><p>新增术语表条目同样走 RFC。错误码、能力 ID、Baggage 键、操作 ID 一经发布不改。</p><h2 id="已采纳的-rfc" tabindex="-1">已采纳的 RFC <a class="header-anchor" href="#已采纳的-rfc" aria-label="Permalink to “已采纳的 RFC”">​</a></h2><table tabindex="0"><thead><tr><th>RFC</th><th>主题</th><th>参考实现</th></tr></thead><tbody><tr><td>0001</td><td>原语层</td><td><code>Primitives</code></td></tr><tr><td>0002</td><td>清单</td><td><code>Kernel</code></td></tr><tr><td>0003</td><td>调用上下文与传播</td><td>各协议适配器</td></tr><tr><td>0004</td><td>管道阶段与排序</td><td><code>Kernel</code></td></tr><tr><td>0005</td><td>领域协议与持久化</td><td><code>Domain</code>、<code>Persistence.*</code></td></tr><tr><td>0006</td><td>缓存、分布式锁与幂等</td><td><code>Caching.*</code></td></tr><tr><td>0007</td><td>多租户</td><td><code>MultiTenancy.*</code></td></tr><tr><td>0008</td><td>认证与授权</td><td><code>Security.*</code></td></tr><tr><td>0009</td><td>消息、CloudEvents 信封与发件箱</td><td><code>Messaging.*</code></td></tr><tr><td>0010</td><td>本地化</td><td><code>Localization.*</code></td></tr><tr><td>0011</td><td>操作契约与 XGI</td><td><code>Kernel</code>、<code>Protocols.*</code></td></tr><tr><td>0012</td><td>对象存储</td><td><code>ObjectStorage.*</code></td></tr><tr><td>0013</td><td>调度</td><td><code>Scheduling.*</code></td></tr><tr><td>0014</td><td>远程配置与密钥</td><td><code>Configuration.*</code></td></tr><tr><td>0015</td><td>审计</td><td><code>Auditing.*</code></td></tr><tr><td>0016</td><td>应用清单与打包</td><td><code>Cli</code></td></tr><tr><td>0017</td><td>进程外插件协议</td><td><code>Plugins.Protocol</code>、<code>Plugins.OutOfProcess</code></td></tr><tr><td>0018</td><td>Wasm 插件</td><td><code>Plugins.Wasm</code></td></tr><tr><td>0019</td><td>远程 Provider</td><td><code>Caching.Remote</code></td></tr><tr><td>0020</td><td>版本迁移</td><td><code>Cli</code></td></tr><tr><td>0021</td><td>工作流</td><td><code>Workflow.*</code></td></tr><tr><td>0022</td><td>AI</td><td><code>AI.*</code></td></tr><tr><td>0023</td><td>可观测性与运行信息</td><td><code>Observability.*</code></td></tr></tbody></table><p>正文见规范仓库的 <code>rfcs/</code> 目录。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/getting-started/concepts">核心概念</a>：这些规范在 .NET 实现里对应什么</li><li><a href="/plugins/out-of-process">进程外插件</a>：用任意语言按规范写插件</li><li><a href="/appendix/contributing">贡献指南</a>：怎样提一个 RFC</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};